// === Tab: mySketch ===
// by SamuelYAN
// more works //
   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

let r;
let points = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  // pixelDensity(5);
  background(0, 0, 95, 100);

  r = 15;
  x_length = int(width / r);
  y_length = int(height / (r * cos(PI / 6)));
  for (var x = 0; x < x_length + 4; x++) {
    points[x] = [];
    for (var y = 0; y < y_length + 4; y++) {
      if (y % 2 == 0) {
        points[x][y] = createVector(
          x * r + (width - x_length * r) / 2,
          y * r + (height - r * y_length) / 2
        );
      } else if (y % 2 == 1) {
        points[x][y] = createVector(
          x * r + (width - x_length * r) / 2 + r / 2,
          y * r + (height - r * y_length) / 2
        );
      }
    }
  }
}

function draw() {
  noFill();
  strokeCap(SQUARE);
  translate(-r, -r);
  for (var x = 0; x < x_length; x++) {
    for (var y = 0; y < y_length; y++) {
      if (x % 2 == 0 && y % 2 == 0) {
        stroke(250, 70, 95, 95);
        strokeWeight(random(1));
        line(
          points[x + 0][y + 3].x,
          points[x + 0][y + 3].y,
          points[x + 3][y + 2].x,
          points[x + 3][y + 2].y
        );
        strokeWeight(random(2));
        line(
          points[x + 3][y + 2].x,
          points[x + 3][y + 2].y,
          points[x + 1][y + 4].x,
          points[x + 1][y + 4].y
        );
        strokeWeight(random(3));
        line(
          points[x + 3][y + 3].x,
          points[x + 3][y + 3].y,
          points[x + 1][y + 2].x,
          points[x + 1][y + 2].y
        );
       stroke(70, 90, 55, 95);
        strokeWeight(random(1));
        line(
          points[x + 1][y + 2].x,
          points[x + 1][y + 2].y,
          points[x + 3][y + 4].x,
          points[x + 3][y + 4].y
        );
        strokeWeight(random(2.5));
        line(
          points[x + 1][y + 1].x,
          points[x + 1][y + 1].y,
          points[x + 2][y + 4].x,
          points[x + 2][y + 4].y
        );
        strokeWeight(random(3));
        line(
          points[x + 2][y + 4].x,
          points[x + 2][y + 4].y,
          points[x + 2][y + 1].x,
          points[x + 2][y + 1].y
        );
      }
    }
  }
 noLoop();
}

function mouseClicked(){
  background(0, 0, 95, 100);
  loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("OstwaldPattern-002", "png");
  }
}

